package com.kaymlyn.planeteater.claude;

import com.kaymlyn.planeteater.simulation.celestial.Orbiter;
import com.kaymlyn.planeteater.simulation.physics.Itinerary;
import com.kaymlyn.planeteater.simulation.physics.TransferOptimizer;
import com.kaymlyn.planeteater.simulation.vehicles.Spacecraft;

import java.util.List;

/**
 * Example demonstrating how players choose between different transfer strategies
 * 
 * Generated by Claude (Sonnet 4.5)
 */
public class TransferOptimizerExample {

    public static void main(String[] args) {
        // Setup (pseudocode - requires full simulation)
        Spacecraft minerShip = null; // Player's spacecraft
        Orbiter mars = null;         // Starting location
        Orbiter ceres = null;        // Destination asteroid
        
        // Player wants to land on Ceres to mine
        boolean land = true;
        
        // === STEP 1: Generate all possible transfer options ===
        List<TransferOptimizer.TransferOption> options =
            TransferOptimizer.generateTransferOptions(minerShip, mars, ceres, land);
        
        System.out.println(TransferOptimizer.summarizeOptions(options));
        
        // === STEP 2: Player chooses optimization goal ===
        
        // Option A: Player wants fastest delivery (time-critical mission)
        TransferOptimizer.TransferOption fastest = 
            TransferOptimizer.selectBestTransfer(
                options, 
                TransferOptimizer.OptimizationGoal.MINIMUM_TIME);
        
        System.out.println("\n=== FASTEST OPTION ===");
        System.out.println(fastest.getItinerary().getSummary());
        
        // Option B: Player wants most fuel-efficient (limited fuel)
        TransferOptimizer.TransferOption mostEfficient = 
            TransferOptimizer.selectBestTransfer(
                options, 
                TransferOptimizer.OptimizationGoal.MINIMUM_DELTAV);
        
        System.out.println("\n=== MOST EFFICIENT OPTION ===");
        System.out.println(mostEfficient.getItinerary().getSummary());
        
        // Option C: Player wants balanced approach
        TransferOptimizer.TransferOption balanced = 
            TransferOptimizer.selectBestTransfer(
                options, 
                TransferOptimizer.OptimizationGoal.BALANCED);
        
        System.out.println("\n=== BALANCED OPTION ===");
        System.out.println(balanced.getItinerary().getSummary());
        
        // === STEP 3: Player picks one and programs it ===
        
        // Let's say player chooses balanced approach
        Itinerary chosenRoute = balanced.getItinerary();
        
        // Validate spacecraft can execute this plan
        if (!chosenRoute.validateAgainstSpacecraft(minerShip)) {
            System.out.println("\nERROR: Spacecraft cannot execute this route!");
            System.out.println("Reason: " + chosenRoute.getInfeasibilityReason());
            return;
        }
        
        // Program the itinerary
        minerShip.programItinerary(chosenRoute);
        
        // Launch when ready
        if (minerShip.launch()) {
            System.out.println("\nLaunch successful! Transfer in progress...");
            System.out.println("ETA: " + chosenRoute.getTotalFlightTime() / 86400 + " days");
        } else {
            System.out.println("\nLaunch failed!");
        }
    }
    
    /**
     * Example: Player manually reviewing each option before choosing
     */
    public static void manualSelection(
            Spacecraft spacecraft,
            Orbiter origin, 
            Orbiter destination) {
        
        List<TransferOptimizer.TransferOption> options = 
            TransferOptimizer.generateTransferOptions(spacecraft, origin, destination, true);
        
        System.out.println("Available transfer options:");
        System.out.println();
        
        for (int i = 0; i < options.size(); i++) {
            TransferOptimizer.TransferOption opt = options.get(i);
            Itinerary it = opt.getItinerary();
            
            System.out.printf("Option %d: %s%n", i + 1, opt.getStrategy());
            System.out.printf("  Delta-V Required: %.1f m/s%n", 
                it.getTravelDeltaV() + it.getLaunchDeltaV() + it.getLandingDeltaV());
            System.out.printf("  Transfer Time: %.2f days%n", 
                it.getTotalFlightTime() / 86400);
            System.out.printf("  Maneuvers: %d%n", it.getNumberOfManeuvers());
            
            // Check if this ship can do it
            double requiredFuel = spacecraft.fuelRequired(
                it.getTravelDeltaV() + it.getLaunchDeltaV() + it.getLandingDeltaV());
            double fuelMargin = spacecraft.getFuelMass() - requiredFuel;
            
            if (fuelMargin > 0) {
                System.out.printf("  Fuel Margin: %.1f kg (%.1f%%)%n", 
                    fuelMargin, 
                    100.0 * fuelMargin / spacecraft.getFuelMass());
            } else {
                System.out.printf("  ⚠ INSUFFICIENT FUEL (need %.1f kg more)%n", -fuelMargin);
            }
            
            System.out.println();
        }
        
        // In a real game, player would select option index
        // For this example, auto-select most efficient that fits
        TransferOptimizer.TransferOption chosen = options.stream()
            .filter(opt -> opt.getItinerary().validateAgainstSpacecraft(spacecraft))
            .findFirst()
            .orElse(null);
        
        if (chosen != null) {
            System.out.println("Selected: " + chosen.getStrategy());
            spacecraft.programItinerary(chosen.getItinerary());
        } else {
            System.out.println("No feasible options available!");
        }
    }
}
